struct Point_2 {
    double x_val, y_val;
    double x() const { return x_val; }
    double y() const { return y_val; }
    Point_2(double x, double y) : x_val(x), y_val(y) {}
};

double cross_product(Point_2 a, Point_2 b, Point_2 c) {
    return (b.x() - a.x()) * (c.y() - a.y()) - (b.y() - a.y()) * (c.x() - a.x());
}

std::vector<Point_2> convex_hull_graham(std::vector<Point_2> points) {
    int n = points.size();
    if (n <= 2) return points;

    int min_idx = 0;
    for (int i = 1; i < n; i++) {
        if (points[i].y() < points[min_idx].y() || (points[i].y() == points[min_idx].y() && points[i].x() < points[min_idx].x())) {
            min_idx = i;
        }
    }
    std::swap(points[0], points[min_idx]);
    Point_2 pivot = points[0];

    std::sort(points.begin() + 1, points.end(), [pivot](const Point_2& a, const Point_2& b) {
        double cp = (a.x() - pivot.x()) * (b.y() - pivot.y()) - (a.y() - pivot.y()) * (b.x() - pivot.x());
        if (cp == 0) {
            double dist_a = (a.x() - pivot.x()) * (a.x() - pivot.x()) + (a.y() - pivot.y()) * (a.y() - pivot.y());
            double dist_b = (b.x() - pivot.x()) * (b.x() - pivot.x()) + (b.y() - pivot.y()) * (b.y() - pivot.y());
            return dist_a < dist_b;
        }
        return cp > 0;
    });

    std::vector<Point_2> hull;
    hull.push_back(points[0]);
    hull.push_back(points[1]);

    for (int i = 2; i < n; i++) {
        while (hull.size() >= 2 && cross_product(hull[hull.size() - 2], hull.back(), points[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(points[i]);
    }
    return hull;
}

int main() {
    std::vector<Point_2> pts = {{0, 0}, {1, 0}, {0, 1}, {1, 1}, {0.5, 0.5}};
    auto hull = convex_hull_graham(pts);
    return hull.size() == 4 ? 0 : 1;
}

